# cc-compat.sh — evaluates a Claude Code version against the one csm was
# last checked with (SESSION_TESTED_VERSION in src/session.h).
#
# Usage: tools/cc-compat/cc-compat.sh [-p] [NEW_VERSION]
#   NEW_VERSION  default: the newest one in ~/.local/share/claude/versions
#   -p           also run cc-probe.sh (starts "claude -p")
#
# Steps, each with its full output in t/cc-compat:
#   1. cc-code.pl on both executables, and a diff of the code snapshots
#      (code-OLD-NEW.diff); a snapshot of the tested version is kept, so
#      the comparison works after its executable is gone,
#   2. cc-data.pl on the real session data, read only (data-NEW.txt),
#   3. whether csm sees a running Claude Code (exit status 3 on a fix of
#      two missing paths in an empty configuration — nothing to change),
#   4. with -p, cc-probe.sh (probe-NEW.txt).
# Reading the outputs and deciding stays with a person.

ROOT=$(cd "$(dirname "$0")/../.." && pwd -P)
TOOLS=$ROOT/tools/cc-compat
OUT=$ROOT/t/cc-compat
VERSIONS=$HOME/.local/share/claude/versions
PROBE=0

while getopts p OPT
do
	case $OPT
	in
	p)
		PROBE=1
		;;
	*)
		echo "usage: cc-compat.sh [-p] [NEW_VERSION]" >&2
		exit 2
		;;
	esac
done
shift $((OPTIND - 1))

TESTED=$(sed -n 's/^#define SESSION_TESTED_VERSION "\(.*\)"$/\1/p' "$ROOT/src/session.h")
if [ -z "$TESTED" ]
then
	echo "cc-compat: SESSION_TESTED_VERSION not found in src/session.h" >&2
	exit 2
fi
NEW=$1
if [ -z "$NEW" ]
then
	NEW=$(ls "$VERSIONS" 2>/dev/null | sort -t. -k1,1n -k2,2n -k3,3n | tail -1)
fi
if [ ! -f "$VERSIONS/$NEW" ]
then
	echo "cc-compat: no Claude Code $NEW in $VERSIONS" >&2
	exit 2
fi
mkdir -p "$OUT/code" || exit 1
echo "csm checked with Claude Code $TESTED; evaluating $NEW"
echo

echo "== 1. code"
if [ -f "$VERSIONS/$TESTED" ]
then
	perl "$TOOLS/cc-code.pl" -q -o "$OUT/code/$TESTED" "$VERSIONS/$TESTED" | sed "s/^/$TESTED: /"
elif [ -d "$OUT/code/$TESTED" ]
then
	echo "$TESTED: executable gone, using the snapshot in t/cc-compat/code/$TESTED"
else
	echo "$TESTED: neither the executable nor a snapshot; no code comparison"
fi
perl "$TOOLS/cc-code.pl" -o "$OUT/code/$NEW" "$VERSIONS/$NEW" >"$OUT/code-$NEW.txt"
CODE=$?
grep -v '^ok ' "$OUT/code-$NEW.txt" | sed "s/^/$NEW: /"
if [ -d "$OUT/code/$TESTED" ] && [ "$TESTED" != "$NEW" ]
then
	(cd "$OUT/code" && diff -r -u -a "$TESTED" "$NEW") >"$OUT/code-$TESTED-$NEW.diff"
	echo "snapshot diff: $(grep -c '^[-+][^-+]' "$OUT/code-$TESTED-$NEW.diff") changed lines in" \
	    "$(grep -c '^diff ' "$OUT/code-$TESTED-$NEW.diff") files -> t/cc-compat/code-$TESTED-$NEW.diff"
fi
echo

echo "== 2. session data (read only)"
perl "$TOOLS/cc-data.pl" "$TESTED" "$NEW" >"$OUT/data-$NEW.txt" 2>&1
tail -1 "$OUT/data-$NEW.txt"
sed -n '/^Problems:/,/^$/p' "$OUT/data-$NEW.txt" | grep -v '^Problems:'
echo "-> t/cc-compat/data-$NEW.txt"
echo

echo "== 3. running Claude Code"
if [ -x "$ROOT/csm" ]
then
	mkdir -p "$OUT/empty/config"
	CLAUDE_CONFIG_DIR=$OUT/empty/config "$ROOT/csm" -F "$OUT/empty/missing-old" "$OUT/empty/missing-new" >/dev/null 2>&1
	case $?
	in
	3)
		echo "ok   csm detects a running Claude Code"
		;;
	*)
		echo "--   csm sees no running Claude Code; right only if none is open"
		;;
	esac
else
	echo "--   csm is not built; skipped"
fi
echo

PROBE_RC=0
if [ "$PROBE" -eq 1 ]
then
	echo "== 4. probe (claude -p)"
	sh "$TOOLS/cc-probe.sh" "$VERSIONS/$NEW" >"$OUT/probe-$NEW.txt" 2>&1
	PROBE_RC=$?
	grep -v '^ok ' "$OUT/probe-$NEW.txt"
	echo "-> t/cc-compat/probe-$NEW.txt"
	echo
fi

if [ "$CODE" -eq 0 ] && [ "$PROBE_RC" -eq 0 ]
then
	echo "cc-compat: checks passed; read the snapshot diff and the data differences before raising SESSION_TESTED_VERSION"
else
	echo "cc-compat: checks failed; csm needs a look before $NEW is accepted"
fi
[ "$CODE" -eq 0 ] && [ "$PROBE_RC" -eq 0 ]
